def main():
 if ROOT.exists():raise FileExistsError(ROOT)
 if set(map(len,CASES.values()))!={20}:raise ValueError('Five20-scenario slices required')
 ROOT.mkdir();cases=[]
 for category,rows in CASES.items():
  for row in rows:
   a,b,c,x,y,z=row;cases.append(dict(id=len(cases)+1,category=category,scenario_family=digest(['core-english-scenario-v1',a]),turns=[dict(user=u,success_criterion=k) for u,k in zip((a,b,c),(x,y,z))]))
 protocol=dict(creator='Navneet Prabhakar',max_new_tokens=128,conversations=cases,human_attestation=False,kind='authored-core-english-development-v1',scope='New everyday scenario development cases; generic English skills recur. No specialist facts, teacher repair or model-produced reference answers. Not a random population sample or fresh final benchmark; no semantic-family certification from exact/near checks. Each turn judged against its exact request and actual student history. Full conversation success requires all3turns. Broader75%correct-turn target remains separate from narrower groundedQA and original full-project final gates.')
 p=ROOT/'protocol.json';p.write_text(json.dumps(protocol,ensure_ascii=False,indent=2)+'\n')
 manifest=dict(creator='Navneet Prabhakar',complete=True,training_approved=False,human_attestation=False,conversations=100,requested_turns=300,slices={k:20 for k in CASES},protocol_sha256=sha(p),authoring_script_sha256=sha(__file__),scope='Frozen while grounded training is active, before any captures on this authored suite. No student output used for case selection. Admission/contamination audit and separately bounded exact-checkpoint capture precede scoring. Development only; retain all cases/failures without post-score removal.')
 (ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n');print('Frozen100 coreEnglish scenarios',sha(p),'bytes',p.stat().st_size)
if __name__=='__main__':main()
